import{_ as p,a0 as l,w as o,s as i,ao as b,I as r,x as e,a1 as n,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"為什麼説 Kubernetes 是一輛翻斗車 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼説 Kubernetes 是一輛翻斗車 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼説 Kubernetes 是一輛翻斗車 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼説 Kubernetes 是一輛翻斗車 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190604 Kubernetes is a dump truck- Here-s why","title":"為什麼説 Kubernetes 是一輛翻斗車","tag":"201906","desc":""},"relativePath":"201906/20190604 Kubernetes is a dump truck- Here-s why.md","filePath":"[post].md"}'),d={name:"201906/20190604 Kubernetes is a dump truck- Here-s why.md"};function m(a,t,f,T,k,K){const s=l("Link");return o(),i("div",null,[t[18]||(t[18]=b('<h1 id="為什麼説-kubernetes-是一輛翻斗車" tabindex="-1">為什麼説 Kubernetes 是一輛翻斗車 <a class="header-anchor" href="#為什麼説-kubernetes-是一輛翻斗車" aria-label="Permalink to “為什麼説 Kubernetes 是一輛翻斗車”">​</a></h1><blockquote><p>翻斗車是解決各種基本業務問題的優雅解決方案。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201906/24/012846v737bts00uwk3qd7.jpg" alt=""></p><p>這篇文章寫於 Kubernetes 的生日（6 月 7 日星期五）前夕。</p><p>翻斗車很優雅。説真的，不信你聽我説。它們以優雅的方式解決了各種各樣的技術問題。它們可以搬動泥土、礫石、岩石、煤炭、建築材料或道路上的障礙。它們甚至可以拉動拖車及它們上面的其他重型設備。你可以給一輛翻斗車裝上五噸泥土，然後自駕遊遍全國。對於像我這樣的電腦極客來説，那就是優雅。</p><p>但是，它們並不容易使用。駕駛翻斗車需要特殊的駕駛執照。它們也不容易裝配和維護。購買翻斗車和各種維護時要做很多選擇。但是，它們可以優雅的搬動那些垃圾。</p><p>你知道搬動垃圾有什麼不優雅的地方嗎？假如你有一款新型的緊湊型轎車，它們到處可以買到，易於駕駛、更易於維護。但是，用它們來裝泥土就很糟糕。這需要跑 200 趟才能運走 5 噸垃圾，而且，之後沒人再會想要這輛車了。</p><p>好吧，你可以買一輛出售的翻斗車，而不是想自己造一輛。但是我不同，我是個極客，我喜歡自己造東西。但……</p><p>如果你擁有一家建築公司，你就不會想着自己造一輛翻斗車。你肯定不會維持一條供應鏈來重構翻斗車（這可是一條很大的供應鏈）。但你可以學會駕駛一輛。</p>',9)),r("p",null,[t[1]||(t[1]=e("好吧，我的這個比喻很粗糙，但很容易理解。易用性是相對的，易於維護是相對的，易於裝配也是相對的。這實際上取決於你想要做什麼。",-1)),n(s,{href:"https://kubernetes.io/"},{default:u(()=>[...t[0]||(t[0]=[e("Kubernetes",-1)])]),_:1}),t[2]||(t[2]=e(" 也不例外。",-1))]),t[19]||(t[19]=r("p",null,"一次性構建 Kubernetes 並不太難。配置好 Kubernetes 呢？好吧，這稍微難一些。你如何看待 KubeCon？它們又宣佈了多少新項目？哪些是“真實的”呢？而你應該學習哪些？你對 Harbour、TikV、NATD、Vitess，開放策略代理有多深入的瞭解？更不用説 Envoy、eBPF 和 Linux 中的一系列底層技術？這就像是 1904 年工業革命爆發時建造翻斗車一樣，你要弄清楚使用的螺釘、螺栓、金屬和活塞。（有沒有蒸汽朋克在這裏嗎？）",-1)),t[20]||(t[20]=r("p",null,"像翻斗車一樣構造和配置 Kubernetes 是一個技術問題，如果你從事金融服務、零售、生物研究、食品服務等等，這可能不是你應該做的事情。但是，學習如何駕駛 Kubernetes 肯定是你應該學習的東西。",-1)),t[21]||(t[21]=r("p",null,"Kubernetes 就像一輛翻斗車，因其可以解決的各種技術問題（以及它所拖帶的生態系統）而優雅。所以，我會給你一句引用的話，這是我的一位計算機科學教授在我大學的第一年告訴我們的，她説，“有一天，你會看到一段代碼並對自己説，‘真特麼優雅！’”",-1)),t[22]||(t[22]=r("p",null,"Kubernetes 很優雅。",-1)),t[23]||(t[23]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),n(s,{href:"https://opensource.com/article/19/6/kubernetes-dump-truck"},{default:u(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/19/6/kubernetes-dump-truck",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=e("作者：",-1)),n(s,{href:"https://opensource.com/users/fatherlinux"},{default:u(()=>[...t[5]||(t[5]=[e("Scott McCarty",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),n(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:u(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:u(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const w=p(d,[["render",m]]);export{g as __pageData,w as default};
